from pathlib import Path
import json
import pandas as pd

ROOT=Path(__file__).resolve().parents[1]
CAT=ROOT/"audit"/"raw_variable_catalog_v1.csv"
CONCEPTS={
 "employed_days_per_week":("Employed-work days per week","Work organization","Past-year average work days per week, asked within the wage-employment route. In 2020, weeks on paid vacation and fully paid sick leave are excluded; retain wave-specific denominators. A missing field can mean not routed or not eligible; do not recode it as zero."),
 "employed_hours_per_day":("Employed-work hours per day","Work organization","Past-year average hours per day excluding meal breaks and including paid/unpaid overtime in later questionnaires. Confirm 2011 wording and route before combining; retain source values and questionnaire range checks."),
 "employed_work_months_past_year_2011_2018":("Months worked in employed work in the past year (2011-2018)","Work intensity","2011/2013/2015 FE001 and 2018 FE001 ask months worked in the past year in the employed-work module. The 2011-2015 range is 0-12 and counts paid vacation/sick leave without wage deduction; 2018 uses 1-12 and defines a working month as at least one day, while counting paid vacation and fully paid sick leave. Dispatched workers (and in 2018 workers hired by individuals) report the actual workplace rather than the dispatch entity. Preserve each wave's scale and denominator; do not merge with non-farm self-employment FH001 or 2020 FE001 (side-job days/week)."),
 "self_employed_days_per_week":("Non-farm self-employed/family-business days per week","Work organization","2011–2018 FH is explicitly non-farm self-employed and unpaid work for family business; 2020 FD is non-agricultural self-employed work. Do not merge with wage employment or agricultural self-employment schedule."),
 "self_employed_hours_per_day":("Non-farm self-employed/family-business hours per day","Work organization","2011–2018 FH is explicitly non-farm self-employed and unpaid work for family business; 2020 FD is non-agricultural self-employed work. Later questionnaire specifies hours/day; retain this separate route."),
 "written_labor_contract":("Written labor contract","Employment conditions","Candidate employment-protection indicator. 2011 label says labor contract without ‘written’; 2013–2020 wording explicitly asks whether a written contract exists, so 2011 requires separate review."),
 "work_injury_protection":("Employer-provided work-injury protection","Employment conditions","Sparse candidate. 2011/2013 ask whether employer provides worker-injury insurance; 2018 asks employer-provided workplace accident insurance. Treat as related but not automatically identical; preserve the checklist route and no continuous 5-wave coverage."),
 "current_employer_organization_type":("Type of current employer organization","Employment conditions","Nominal type of the current employer/work unit. Categories and question routes vary by wave; preserve original response labels and do not collapse employer organization type with job arrangement or occupation."),
 "most_recent_job_employer_organization_type_2011_2018":("Employer organization type of most recent job among respondents not currently working (2011-2018)","Work history and labor-market transitions","FL014 is asked in the most-recent-job section for respondents not currently working. It records the former employer/work-unit type, not current employment. Preserve wave-specific nominal response menus (including other-category wording) and the nonworking/previous-work denominator. Do not merge with current employed-work FD002/FC002 or with FL016 firm-ownership type."),
 "current_workplace_location_relative_to_residence_2011_2018":("Current workplace location relative to residence (2011-2018)","Workplace context","FD004 records the current workplace location in the employed-work module. 2011 categories are same village/community, other village/community in county/city, another county/city in province, and another province; 2013-2018 use wave-specific categories relative to permanent/current residence and include an abroad option in some waves. Treat as a coarse self-reported geographic context, not commute distance, air pollution, or neighborhood exposure. Preserve the original categories and eligible current-employed denominator; the identically named 2020 FD004 is number of employees and is explicitly excluded."),
 "nonfarm_self_employment_months_past_year_2011_2020":("Months worked in non-farm self-employment or unpaid family business in the past year (2011-2020)","Work intensity","2011-2018 FH001 is asked within non-farm self-employed/unpaid family-business routes; 2020 FD007 uses CAPI wording for the selected self-employed or family-business activity. Preserve activity, route, and 0-12/month range; skipped values do not mean zero."),
 "current_nonfarm_job_arrangement_2011_2015":("Current non-farm job arrangement (2011-2015)","Employment conditions","FC020 is the main job type when the respondent has multiple non-farm jobs; FC021 asks the type when there is no multiple-job branch. Categories are 1=employed, 2=self-employed, 3=unpaid family business. Preserve the different routes and do not treat either as all-work status."),
 "multiple_current_nonfarm_jobs_2011_2015":("More than one current non-farm job (2011-2015)","Work organization","2011-2015 FC019 asks whether the respondent currently has more than one non-agricultural job; the 2011 questionnaire explicitly excludes agricultural work although its short codebook label is broader. Preserve the yes/no route and do not infer a side-job count from No or skip."),
 "employer_provided_housing_fund_2011_2013":("Employer-provided housing provident fund (2011-2013)","Employment benefits","FG014 asks whether the current employer provides a housing provident fund. This is a workplace benefit report, not the respondent's own housing-fund enrollment or balance; preserve the current-employed-job route."),
 "unpaid_family_business_occupation_code_2011":("Occupation code for unpaid family-business work (2011)","Occupation and industry","FH015 occupation is asked on the unpaid family-business route (FC020=3 or FC021=3). Preserve GB and ISCO classifications separately; do not crosswalk code systems and review rare detailed codes for disclosure before public release."),
 "agricultural_wage_employer_count_past_month_2011_2013":("Number of farm employers in the past month (2011-2013)","Work organization","FC002 asks the number of other farm households/employers the respondent worked for in the past month, after FC001=Yes for paid agricultural work at least 10 days in the past year. It counts employers, not jobs or days. Preserve the past-month reference and FC001 route; the 2020 FC002 is a different employer-type item."),
 "formal_employee_status":("Formal employee status","Employment conditions","Current job relationship candidate. 2011–2018 fields are mapped; 2020 reuses fd007 for work months, so do not treat it as equivalent."),
 "employment_type":("Employment type","Employment conditions","Wave-limited classification of current employment arrangement; codes/categories must be reviewed by wave."),
 "industry_code":("Current job industry code","Occupation and industry","2011 source code only; classification code is nominal/categorical and codebook version must be preserved."),
 "occupation_code_gb":("Current occupation code (GB classification)","Occupation and industry","2011 source code only; preserve Chinese GB classification version and codebook categories."),
 "occupation_code_isco":("Current occupation code (ISCO)","Occupation and industry","2011 source code only; keep separate from GB occupation codes; occupational code values require disclosure review before public release."),
 "employment_contract_duration":("Agreed employment contract duration","Employment conditions","2011–2020 contract period; 2020 distinguishes defined, undefined, and project-term contracts, with conditional year/month components. Preserve the nominal period type and duration separately, and retain -1/997/999 as special codes."),
 "employment_contract_renewed":("Current employment contract renewal status","Employment conditions","Asked among current employees with a labor contract; structural skips do not mean no renewal."),
 "employment_contract_renewal_count":("Current employment contract renewal count","Employment conditions","Conditional count after renewal status; not a universal job stability measure."),
 "expected_time_current_workplace":("Expected time to continue at current workplace","Employment conditions","Self-reported expectation, not observed job tenure; route and response units require wave review."),
 "employer_pension_insurance":("Employer-provided pension insurance","Employment benefits","2011/2013 employer benefit checklist; not equivalent to individual pension enrollment/receipt."),
 "employer_health_insurance":("Employer-provided health insurance","Employment benefits","2011/2013 employer benefit checklist; distinct from current health insurance coverage."),
 "employer_unemployment_insurance":("Employer-provided unemployment insurance","Employment benefits","2011/2013 employer benefit checklist; a workplace benefit report, not individual benefit receipt."),
 "employer_maternity_insurance":("Employer-provided maternity insurance","Employment benefits","2011/2013 employer benefit checklist; wave and respondent eligibility limit coverage."),
 "employer_no_insurance_report":("Employer reported no insurance benefits","Employment benefits","Checklist none-of-the-above item; preserve its special role and do not interpret it as a measured absence if the item is skipped."),
 "employer_provided_fringe_benefits_2018":("Current-employer fringe benefits (2018)","Employment benefits","2018 FG001 is a select-all-that-apply checklist for the current workplace/employer: lunch, breakfast, dinner, meal allowance, transport allowance, free housing, housing allowance, company car, shuttle, other allowance, and none. Each *_sN field is a checkbox slot coded 9 when selected and 0 when not selected in the codebook. Preserve the employed-work route and distinguish selected 'None' from missing/unrouted fields; FG002 allowance amounts are separate conditional fields."),
 "employer_supplementary_health_insurance_2018":("Employer-purchased supplementary health insurance (2018)","Employment benefits","2018 FD034_W4 asks whether the employer purchases supplementary commercial medical insurance, described as outpatient coverage distinct from accident insurance. This is employer purchase, not individual enrollment or a health outcome; preserve the current-job route and wave-specific coverage."),
 "employer_fringe_benefit_monthly_value_2018":("Monthly monetary value of current-employer fringe benefits (2018)","Employment benefits","2018 FG002 records the monthly monetary value corresponding to each benefit selected in FG001. Keep each benefit slot separate, use yuan/month, and retain the conditional selected-benefit/current-employer universe. These are reported benefit values, not wage or household income; check nonresponse, units, and extremes in the approved release before analysis."),
 "current_employer_ownership_type_2013_2018":("Current employer ownership type (2013-2018)","Employment conditions","FD010 asks ownership type of the current employer/workplace and provides a ten-category nominal menu. Preserve the firm/employer route and wave-specific categories; this is distinct from the respondent's previous business ownership and from employer organization type."),
 "side_job_count_2013_2015":("Current side-job count excluding the main job (2013-2015)","Work organization","FJ001 asks how many jobs the respondent currently holds excluding the main job (range 1-20). Keep the current side-job route and wave-specific eligibility; do not interpret structural skips as zero or combine with 2011/2018 counts whose scopes/routes differ."),
 "side_job_hours_per_week_2013_2015":("Average weekly hours at current side jobs (2013-2015)","Work intensity","FJ002 asks average weekly hours across side job(s), excluding the main job (questionnaire range 0-168). Preserve the routed side-job universe and do not treat missing as zero."),
 "side_job_monthly_income_2013_2015":("Average monthly income from current side jobs (2013-2015)","Work intensity","FJ003 asks average monthly income/wage from side jobs other than the main job, in yuan per month. Preserve the routed universe and distinguish from main-job wages and household income."),
 "current_employer_start_date_components_2013_2020":("Start year and month at current employer (2013-2020)","Work history and labor-market transitions","FD011_1/_2 in 2013-2018 and FC019_1/_2 in 2020 record the year and month work began for the current employer. FD011_W2_2_1/_2 in 2013/2015 are conditional correction-route dates when the respondent denies the prior-wave employment record; FC018_1/_2 in 2020 are another conditional corrected-date route when the preload is denied. These are date components, not a derived tenure measure. Preserve route-specific priority and do not include a regular and correction date twice; retain the 2020 -1 unable-to-recall code before deriving any tenure."),
 "current_job_start_date_2013":("Start year and month in the current job (2013)","Work history and labor-market transitions","FD012_W2_5 asks when the respondent started the current job in its 2013 routed work-history branch. Preserve the prior-wave/current-job eligibility path and keep separate from FD013_W2_5 (start of current work/task), current-employer FD011, self-employment business start, and prior-job dates. These are year/month components, not derived tenure."),
 "current_work_activity_start_date_2013":("Start year and month doing the current work activity (2013)","Work history and labor-market transitions","FD013_W2_5 asks when the respondent started doing the current work, conditional on current job/work details and prior-wave comparison. Keep distinct from FD012_W2_5 (current job), current-employer FD011, and business start dates; preserve its wave-specific route and year/month components."),
 "current_nonfarm_self_employment_start_date_2013_2015":("Start year and month at current non-farm self-employed business (2013-2015)","Work history and labor-market transitions","FH008 records when the respondent started working at the current non-farm self-employed company/workplace. In 2013/2015 the follow-up is skipped when the returning respondent reports the same business as at the prior interview. Preserve that transition route and the year/month components; do not confuse with the business's founding date or with unpaid-family-business participation. The 2018 FH008 codebook label suggests business start and is excluded pending source-definition reconciliation."),
 "unpaid_family_business_start_date_2013_2018":("Start year and month helping at current unpaid family business (2013-2018)","Work history and labor-market transitions","FH018 records when the respondent began working/helping at the current family business in the unpaid family-business route. Preserve the work-type universe, wave-specific route, and separate year/month components. This is respondent participation start, not business founding date, current employer tenure, or self-employment start."),
 "last_job_start_date_2013_2018":("Start year and month at most recent job (2013-2018)","Work history and labor-market transitions","FL002 records the start date of the most recent job in the retrospective last-job module. The job can be employed, self-employed, unpaid family-business, or agricultural work under the wave-specific route; it is not current-job start or a universal employment-history date. Preserve year/month fields, the nonworking/prior-work denominator, and unknown-month conventions."),
 "last_job_stop_date_2013_2018":("Stop year and month at most recent job (2013-2018)","Work history and labor-market transitions","FL003 records when the respondent stopped the most recent job in the retrospective last-job module. The route and job type vary; 2013/2015/2018 soft checks compare against FL002 and prior interview timing. Preserve year/month fields and unknown-month conventions; do not merge with FK001, which is asked in the non-employment/job-search section."),
 "last_worked_date_nonemployment_2013_2015":("Last worked year and month in non-employment/job-search module (2013-2015)","Work history and labor-market transitions","FK001 asks when the respondent last worked in the non-employment/job-search module, conditional on having worked before. Retain the not-currently-working/prior-work route and year/month components. Keep distinct from FL003's stop date for a specified most recent job; source record is a separate routed report and should not be reconciled without respondent-level data."),
 "same_work_activity_since_prior_interview_2013":("Continued doing the same specific work as at prior interview (2013)","Work history and labor-market transitions","FD012_W2_3 asks whether the respondent was still doing the specific work reported at the prior interview. Preserve the returning-respondent/prior-work route and distinguish continuity of a specific work activity from continuity with the same employer/business; a No response leads to a separate current-work description."),
 "reason_for_stopping_last_job_2018":("Reason for stopping the most recent job or work activity (2018)","Work and employment transitions","FL020_W4 is a single categorical reason asked in the retrospective last-job module, including employed, self-employed, unpaid family-business and farm-work routes. It is not the 2011–2015 multi-select FL020 checklist; preserve the 2018 response menu and prior-work route. Self-reported reason is not a causal attribution."),
 "corrected_prior_nonwork_last_work_exit_date_2020":("Last-work exit date reported after correcting prior-wave work status (2020)","Work history and labor-market transitions","FA018 is asked after FA016 denial and FA017 confirmation that the respondent was not working at the prior interview; it records a retrospective stop-work date. This is a status-correction branch, not the routine working-to-not-working transition FA016. Preserve year/month components and -1 unable-to-recall-month code. DO NOT ANALYZE until the apparent prior-status/date logic and released-data coding are reconciled."),
 "corrected_prior_nonwork_last_work_exit_reason_2020":("Reason for last-work exit reported after correcting prior-wave work status (2020)","Work and employment transitions","FA019 follows the FA016 denial/FA017 confirmation branch and asks why the respondent stopped working. Preserve the retrospective nonworking/prior-status correction route and the official questionnaire categories. This is not the routine FA016 work-exit reason; self-report is not causal evidence. DO NOT ANALYZE until the apparent prior-status/date logic and released-data coding are reconciled."),
 "institutional_formal_employee_status_2011_identity_unresolved":("Formal employee status in public institution (2011; source identity unresolved)","Employment conditions","The 2011 questionnaire asks whether the respondent is a formal employee of an establishment in the institution branch (FD002=2), but the Codebook labels FD009 'Regular Worker'. Keep this isolated from later FD009 branches. Candidate only; DO NOT ANALYZE or harmonize until the source-code identity and approved-release coding are reconciled."),
 "establishment_employment_status_2020_identity_unresolved":("Whether current job is in an establishment (2020; source identity unresolved)","Employment conditions","The 2020 questionnaire asks FC008 'Is [respondent] in the establishment?' while the Codebook calls it 'Formal Employee or Not'. These may represent different constructs. Keep separate from formal-employee indicators; DO NOT ANALYZE until the questionnaire/Codebook identity and approved-release coding are reconciled."),
 "self_employment_employee_status_2011_2015":("Employee status in self-employment/family business (2011-2015)","Employment conditions","FL012 is a three-category nominal item: self-employed with employees, self-employed without employees, or unpaid family-business worker. Preserve all categories and the prior-work/self-employment route; do not collapse this to a simple employee yes/no variable."),
 "last_self_employed_business_employee_count_2018":("Number of employees in last self-employed business (2018)","Work organization","2018 FL012_W4 asks how many people the last business employed (range 0-9999) in the self-employed prior-job module. Keep it separate from 2011-2015 FL012 categorical status and current employer characteristics; preserve the former self-employment route and review extreme values in the approved release."),
 "planned_age_to_stop_working_2011_2015":("Planned age to stop all income-related work (2011-2015)","Retirement expectations","FC018 asks approximate age when the respondent plans to stop work, including income-related activities and unpaid family business. Interviewer instruction codes 0 when the respondent plans to work until physically able. FG015 (employer-insurance route) and FI012 (other-work-unit route) repeat the same definition in 2011/2013. Preserve each source route and do not count duplicate same-wave responses as separate indicators; no priority rule is inferred without respondent-level protocol/data checks. This is an expectation, not observed retirement age; preserve the 0 meaning."),
 "worked_nonagriculturally_last_week_2011_2015":("Any non-agricultural wage/self-employed/family-business work last week (2011-2015)","Current and recent work","FC014 asks whether the respondent worked at least one hour last week in wage work, self-employment, or unpaid family business, excluding agricultural work. Preserve this reference week and non-agricultural scope; do not substitute the distinct last-month or annual work items and do not treat structural skips as No."),
 "public_institution_formal_employee_status_2013_2018":("Formal employee status in the public-institution branch (2013-2018)","Employment conditions","FD009 asks whether the respondent is a formal employee of an establishment (Yes/No) in the public-institution route (FD002=2): 2013/2018 use FD008-FD009; 2015 asks FD009. It is distinct from FD007, asked in the government-employee branch, despite identical wording. Preserve branch-specific denominators; missing/unrouted responses are not No. Do not map 2011 FD009: its questionnaire wording conflicts with the Codebook label 'Regular Worker'."),
 "first_workplace_location_2011_2013":("Coarse location of first workplace (2011/2013)","Work history and labor-market transitions","FB004 reports the location of the respondent's first workplace. 2011 and 2013 use different category anchors (local community/county/province versus permanent-address reference and an abroad category); retain wave-specific nominal menus. This is a retrospective location category, not geocoded residence or measured environmental exposure."),
 "farm_work_gt10days_2011_2015":("Farm work for more than 10 days","Current and recent work","2011–2015 asks whether the respondent engaged in agricultural work for more than 10 days; do not extend this threshold to 2020, whose farm-work item has different wording."),
 "farm_work_presence_2020":("Farm work presence (2020)","Current and recent work","2020 FA001 is a broad farm-work presence item; the >10-day threshold from earlier waves is not stated."),
 "worked_one_hour_last_week_2011":("Worked at least one hour last week (2011)","Current and recent work","2011 reference period is last week; keep separate from the last-month questions in later waves."),
 "worked_one_hour_last_month_2013_2015":("Worked at least one hour last month","Current and recent work","2013 and 2015 ask about last month; retain the reference period and eligibility route."),
 "nonfarm_work_one_hour_last_month_2018":("Nonfarm work for at least one hour last month (2018)","Current and recent work","2018 item explicitly specifies nonfarm work and a last-month reference period; do not infer equivalence with 2020 broad nonfarm-work presence."),
 "temporarily_absent_from_job":("Temporarily absent from a job","Current and recent work","2011–2015 asks about temporary layoff/sick leave; 2018 also includes other leave and on-the-job training. Wave-specific response route must be retained."),
 "expect_return_after_temporary_absence":("Expected return to job after temporary absence","Current and recent work","2011–2018 FA005 and 2020 FA007 are asked on different route wording (temporary absence/vacation); 2011 FC017 is a separate agricultural-wage/other-job absence route. Retain each wave- and item-specific trigger."),
 "paid_during_temporary_absence":("Continued to receive pay during temporary absence","Employment conditions","2011–2018 FA006 and 2020 FA008; conditional on the temporary-absence route and not a universal wage indicator."),
 "return_to_work_since_last_interview_2020":("Return to work since the last interview (2020)","Work and employment transitions","2020 FA013 is asked when the prior interview record says the respondent was not working. It records a reported start date since that interview; code 995 means the prior status is denied and must not be counted as a return-to-work event, 999 is refusal, and month -1 means unable to report the month. Keep the confirmation/correction route and interval definition; this is not a population-wide employment transition measure."),
 "reason_for_return_to_work_2020":("Reason for returning to work (2020)","Work and employment transitions","2020 FA015 is conditional on a reported return to work after a prior nonworking status. It is a single categorical self-reported reason, not a causal attribution; preserve the six questionnaire categories and route. Exclude the free-text FA015_1 from the searchable quantitative atlas."),
 "work_exit_since_last_interview_2020":("Work exit since the last interview (2020)","Work and employment transitions","2020 FA016 is asked when the prior interview record says the respondent was working and asks when work stopped since then. Code 995 denies the prior working status and 999 is refusal; month -1 means unable to report the month. Preserve the specified definition of working, the date interval and the eligibility route; this is not a population-wide unemployment indicator."),
 "capi_any_work_status_2020":("CAPI-derived any-work status (2020)","Current and recent work","2020 questionnaire formula sets XWorking=1 when any of FA001, FA004, FA007, or FA008 equals 1, else 0. This is a generated summary of work-route answers, not an independently asked item. Keep it separate from nonfarm-only FA004 and do not use it in the same model as its source items without a prespecified estimand."),
 "capi_employment_arrangement_binary_2020":("CAPI-derived paid-employment versus self-employed/unpaid work status (2020)","Current and recent work","2020 questionnaire formula derives XEmployed from FA010/FA011 main-job categories and FA002 wage-farm work. Formula value 1 indicates employed work, including paid farm employment; 0 indicates self-employed or unpaid family work. This differs from the English label's literal 'whether self-employed or not'; preserve the formula-derived coding and selected main-job route."),
 "capi_current_job_recent_start_2020":("CAPI-derived recent start of current paid job (2020)","Work and employment transitions","2020 questionnaire formula derives XWorkJustStarted from FC018/FC019 start-date responses and interview year/month: 1=started within the most recent month; 2=started within the past year; 0=neither interval. This is a generated classification, not a reported duration; validate year/month edge cases and any invalid/missing source dates before analysis."),
 "capi_nonworking_to_work_transition_2020":("CAPI-derived transition from nonworking to working (2020)","Work and employment transitions","2020 XGetJob=1 only when prior-wave ZWorking=0 and current XWorking=1, else 0. This is an algorithmic two-wave status transition; it is not the conditional FA013 date-confirmation item. Preserve prior/current status definitions and treat unavailable prior status as requiring validation."),
 "capi_working_to_nonworking_transition_2020":("CAPI-derived transition from working to nonworking (2020)","Work and employment transitions","2020 XQuitJob=1 only when prior-wave ZWorking=1 and current XWorking=0, else 0. This is an algorithmic two-wave status transition; it is not the conditional FA016 reported work-stop date. Preserve prior/current status definitions and treat unavailable prior status as requiring validation."),
 "capi_side_job_days_annualized_2020":("CAPI-derived annualized days in side jobs (2020)","Work intensity","2020 XSideJobDays is FE001 days per week multiplied by 52; the questionnaire sets missing product to 0. This is an annualized derived estimate, not directly reported annual days. Preserve the 52-week assumption, FE001 eligibility, and the questionnaire's missing-to-zero transformation; do not interpret zero as verified no side work without route validation."),
 "weekly_work_days_across_other_jobs_2020":("Weekly work days across all other jobs (2020)","Work intensity","2020 FE001 asks weekly days worked across all other jobs, conditional on the multiple-job roster. It is a days-per-week measure (0-7), not months worked as in FE001 in 2011-2018. XSideJobDays is a related annualized derived field (FE001*52 with missing-to-zero handling), not an equivalent raw measure."),
 "weekly_other_job_hours_per_day_2020":("Daily hours across all other jobs (2020)","Work intensity","2020 FE002 asks usual hours per day across all other jobs after the multiple-job roster. Preserve the 1-24 hard-check and 1-16 soft-check ranges and the roster denominator; do not infer zero hours from a skip."),
 "household_agriculture_months_past_year_2020":("Months worked in own-household agriculture in the past year (2020)","Agricultural work and labor conditions","2020 FB005 asks months worked for own-household agriculture (1-12). It is a household agricultural-work route and is not equivalent to paid farm work or non-farm self-employment."),
 "household_agriculture_days_per_week_2020":("Days per week in own-household agriculture (2020)","Agricultural work and labor conditions","2020 FB006 asks average days per week during a normal work month in the past year. Interviewers enter 1 when the average is below one day/week but work occurs less than four days/month; preserve this floor rule and route."),
 "household_agriculture_hours_per_day_2020":("Hours per workday in own-household agriculture (2020)","Agricultural work and labor conditions","2020 FB007 asks usual hours during a normal workday; preserve the questionnaire's 1-24 hard-check and 1-16 soft-check ranges and eligible household-agriculture route."),
 "household_agricultural_work_satisfaction_2015_2018":("Satisfaction with household agricultural work (2015/2018)","Work organization and psychosocial conditions","FC012_W3 is a five-category self-reported satisfaction item in the household agricultural-work module in 2015 and 2018. This is a subjective work-condition measure, not a global life-satisfaction scale; keep wave-specific labels and eligible routes."),
 "current_workplace_location_relative_to_residence_2020":("Current employer location relative to residence (2020)","Workplace context","2020 FC004 uses current-residence anchors and asks the employer's location, with conditional administrative place-name fields. The parent category is a coarse self-reported context, not commute distance or measured pollution; exclude address strings and do not geocode without approved privacy review."),
 "last_job_occupation_type_2011_2018":("Occupation/type of the most recent job (2011-2018)","Occupation and industry","FL001 is asked in the most-recent-job section for respondents not currently working; categories/classification systems vary by wave. Retain original wave labels and respondent universe; this is not a current occupation."),
 "last_job_workplace_location_2011_2018":("Location category of the most recent job (2011-2018)","Workplace context","FL004 is a retrospective location category for the last job. Preserve the wave-specific geographic anchor and nonworking/prior-job route; it is not a geocoded address, commute distance, or environmental concentration."),
 "last_job_employer_still_exists_2011_2018":("Whether the last employer/work unit still exists (2011-2018)","Work history and labor-market transitions","FL007 is a retrospective employer/work-unit status item in the last-job module. It is not a current employment status; preserve wave-specific categories and the prior-job denominator."),
 "last_job_worker_arrangement_2011_2018":("Worker arrangement in the most recent job (2011-2018)","Employment conditions","FL013 classifies the respondent's worker arrangement in a past job; 2018 categories explicitly distinguish formal employee, contracted and temporary work. Keep wave-specific response labels and last-job routing; do not equate with current-job formal-employee status."),
 "household_agriculture_main_work_type_2018_2020":("Main work type in own-household agriculture (2018/2020)","Agricultural work and labor conditions","FC023_W4 (2018) and FB003 (2020) classify the respondent's main household-farm activity, with different source menus. Preserve wave-specific categories and the household-agriculture route; do not recode the menus as a common occupational scale without review."),
 "paid_agricultural_workplace_location_2011_2013":("Location category of paid agricultural work (2011/2013)","Workplace context","FC003 is asked in the paid agricultural-work route. Preserve its source location categories and work eligibility; it is a coarse self-reported context, not commute distance, geocoded location, or measured pollution."),
 "household_agricultural_workplace_location_2011_2018":("Location category of household agricultural work (2011-2018)","Workplace context","FC012 is asked in the own-household agricultural-work module. Geographic anchors vary by wave; retain source categories and route. It is not an address, commute distance, or environmental concentration."),
 "household_agricultural_workplace_location_2020":("Location of household farm work (2020)","Workplace context","2020 FB001 records the location of farm work within the agricultural-work module. Preserve the official categories and eligible route; do not geocode detailed place names or treat this as a measured environmental concentration."),
 "nonfarm_self_employment_business_location_2011_2020":("Location category of non-farm self-employment business (2011-2020)","Workplace context","FH006 in 2011-2018 and FD002 in 2020 locate a self-employment business. Preserve wave-specific location categories and work route; this coarse report is not commute distance, geocoded location, or measured pollution."),
 "unpaid_family_business_location_2011_2018":("Location category of unpaid family-business work (2011-2018)","Workplace context","FH013 records the location of the family business/workplace. Preserve wave-specific categories and the unpaid family-business route; this is not commute distance, geocoded location, or measured pollution."),
 "same_employer_since_last_interview_2013_2020":("Same employer as at prior interview (2013-2020)","Work history and labor-market transitions","2013/2015 FA006_W2_2A_3 asks whether the respondent still works for the prior-wave employer after the prior employer record is routed; 2018 FD003_W4_1/_2 and 2020 FC003 compare current employer through wave-specific confirmation/correction routes. Preserve wave-specific prior/current job universe, employer-name confirmation, and special deny-record responses. This is employment continuity, not a job-quality measure."),
 "agricultural_work_stop_date_since_last_interview_2013_2015":("Stop date of prior-wave agricultural work (2013/2015)","Work history and labor-market transitions","FA006_W2_1_1/_2 asks when the respondent stopped agricultural work reported at the prior interview, conditional on the prior-wave agricultural-work route. Preserve year and month separately and do not infer a date when the respondent denies the preload."),
 "reason_for_stopping_prior_wave_agricultural_work_2013_2015":("Reason for stopping prior-wave agricultural work (2013/2015)","Work history and labor-market transitions","FA006_W2_1A is a single categorical reason after the prior-wave agricultural-work stop route. Preserve the source menu and route; this is not a causal attribution or the distinct last-job FL020 checklist."),
 "agricultural_work_start_date_since_last_interview_2013_2015":("Start date of agricultural work since prior interview (2013/2015)","Work history and labor-market transitions","FA006_W2_2_1/_2 asks when agricultural work began after the prior interview for respondents whose prior-wave work status did not include agricultural work. Preserve year/month and the prior-wave work-status denominator; do not treat the alternate answer that the respondent already did agricultural work as a new start."),
 "prior_wave_other_job_stop_date_2013_2015":("Stop date of job reported at prior interview (2013/2015)","Work history and labor-market transitions","FA006_W2_3_1/_2 records when the prior-wave non-agricultural job ended after its employer/business continuity route. Keep distinct from the agricultural-work stop date and preserve the employed/self-employed/unpaid-family-business route."),
 "reason_for_stopping_prior_wave_other_job_2013_2015":("Reason for stopping job reported at prior interview (2013/2015)","Work history and labor-market transitions","FA006_W2_4 is a single categorical reason after the prior-wave non-agricultural job stop route. Preserve the source menu and route; this is not a causal attribution or the multi-select last-job FL020 item."),
 "same_unpaid_family_business_since_last_interview_2013_2015":("Same unpaid family business as at prior interview (2013/2015)","Work history and labor-market transitions","FA006_W2_2C_3 checks whether the respondent remains in the prior-wave unpaid family business. Preserve its business-name preload correction route and keep separate from paid-employer continuity and current work arrangement."),
 "wage_payer_source_2011_2020":("Source paying wages for current work (2011-2020)","Employment conditions","FD001 in 2011-2018 and FC001 in 2020 identify whether wages are paid by the workplace/employer, dispatch company, or an individual. Retain wave-specific response options and the current paid-work route; this is distinct from employer organization type."),
 "current_main_job_arrangement_2018":("Current main-job arrangement by work type (2018)","Employment conditions","The 2018 FC020_W4 and FC021_W4 fields classify the main job after work-type and multiple-job routing; XF7 is CAPI-derived from those fields. Preserve each route and original categories. XF7 duplicates source information and must not be entered alongside source fields in one model without a prespecified estimand."),
 "multiple_current_jobs_by_work_type_2018":("Multiple current jobs by agricultural/non-agricultural work type (2018)","Work organization","FC019_W4_B/C/E/F ask whether there is more than one job in specific agricultural-employed or non-agricultural work combinations. These are route-specific status fields, not a universal job count; preserve source combinations and do not turn skips into No."),
 "household_agriculture_main_work_type_2018_2020":("Main work type in own-household agriculture (2018/2020)","Agricultural work and labor conditions","FC023_W4 (2018) and FB003 (2020) classify the respondent's main household-farm activity, with different source menus. Preserve wave-specific categories and the household-agriculture route; do not recode the menus as a common occupational scale without review."),
 "last_job_agricultural_occupation_type_2018":("Occupation type of the last agricultural job (2018)","Occupation and industry","FL004_W4_2 is asked in the prior-job section for agricultural work and classifies the work as manual labor, management, machine operation, or other. Keep it separate from current household-farm occupation and general last-job type."),
 "employer_purchased_work_accident_insurance_maximum_payout_2015_2018":("Maximum payout from employer-purchased work-accident insurance (2015/2018)","Employment benefits","FD033_W3 reports the maximum benefit payable after a severe workplace accident, conditional on FD032_W3=Yes. Preserve yuan amount, the insurance-selection route, and wave-specific wording; this is a reported benefit ceiling, not a health outcome or observed compensation."),
 "nonwork_to_work_start_since_last_interview_2018":("Start date of work after prior-wave nonworking status (2018)","Work and employment transitions","FA010_W4 is asked when prior-wave status indicated not working and current status indicates working. Preserve its correction option ('I was working'), conditional year/month, -1 unable-to-recall code, and prior/current status definition; this is a two-wave transition, not a population-wide work start."),
 "reason_for_nonwork_to_work_transition_2018":("Reason for starting work after prior-wave nonworking status (2018)","Work and employment transitions","FA010_W4_3 is a conditional self-reported reason for starting work after a prior-wave nonworking status. Preserve the five source categories; it is not a causal attribution."),
 "job_type_at_nonwork_to_work_transition_2018":("Job type after starting work from prior-wave nonworking status (2018)","Work and employment transitions","FA010_W4_4 describes the first/current work type after a prior-wave nonworking status. Preserve the five nominal categories and route; this is not a job-quality scale."),
 "work_exit_since_last_interview_2018":("Work exit date since prior interview (2018)","Work and employment transitions","FA011_W4 is asked when prior-wave status indicated working and current status indicates not working. It includes a conditional alternate last-job end date when the respondent denies working in the prior interview; preserve both date routes, -1 recall codes, and the prior/current status gate."),
 "reason_for_work_exit_since_last_interview_2018":("Reason for work exit since prior interview (2018)","Work and employment transitions","FA011_W4_3 is conditional on a reported work exit after a prior-wave working status. Preserve its source categories and the prior/current status route; this is a self-reported reason, not a causal estimate."),
 "last_job_type_at_work_exit_2018":("Last-job type at work exit (2018)","Work and employment transitions","FA011_W4_2 classifies the last job after the conditional work-exit route. Preserve its five nominal categories and the respondent's prior-wave work-status context."),
 "severance_benefit_at_work_exit_2018":("Severance benefit and eligible service years at work exit (2018)","Employment separation benefits","FA011_W4_4/_5 are conditional on the work-exit route and distinguish severance from retirement allowance. Preserve receipt, amount/form, eligible service-year components, and the forced/voluntary exit route; do not infer zero from skipped follow-ups."),
 "transition_household_farm_only_to_other_work_2018":("Transition from household-farm-only work to other work (2018)","Work and employment transitions","FA012_W4 is conditional on a prior-wave household-agricultural-only work status and records transition timing, start of the current main non-farm/other job, and reason. Preserve the two date components separately and the prior/current work-type route; -1 means time not recalled."),
 "transition_other_work_to_household_farm_only_2018":("Transition from other work to household-farm-only work (2018)","Work and employment transitions","FA013_W4 is conditional on prior-wave work other than household agriculture and records when other work ended, when household-farm-only status began, and the reason. Preserve both date pairs, -1 recall codes, and the prior/current work-type route."),
 "transition_employed_to_nonfarm_selfemployment_2018":("Transition from employed work to non-farm self-employment (2018)","Work and employment transitions","FA014_W4 records leaving the prior-wave employed job, starting the current non-farm self-employed/family-business job, and the reason. The relative who took over the prior business is a separate conditional relationship response; preserve the event route, date components, and source categories."),
 "transition_nonfarm_selfemployment_to_employed_2018":("Transition from non-farm self-employment to employed work (2018)","Work and employment transitions","FA015_W4 records leaving prior-wave non-farm self-employment, starting the current employed job, and the reason. Business transfer to a relative is a separate conditional relationship response; preserve the event route, date components, and source categories."),
 "reason_for_employer_change_since_last_interview_2018":("Reason for current-employer change since prior interview (2018)","Work and employment transitions","FD003_W4_3 follows the routed same-employer comparison and records the reported reason for employer change. Preserve the source categories and do not interpret as causal attribution."),
 "reason_for_social_insurance_contribution_through_other_unit_2011_2013":("Reason for paying social insurance through another work unit (2011/2013)","Employment conditions and social protection","FG006 and FI004 ask why the respondent contributes through another work unit. Preserve the five source categories and the specific social-insurance route; this is a work/social-protection context report, not an individual contribution amount."),
 "social_insurance_contribution_workunit_location_2011_2013":("Location category of social-insurance contribution work unit (2011/2013)","Workplace context","FG007 records same city, another city in the same province, or another province for the work unit through which social insurance is contributed. Keep its conditional route and coarse source categories; no free-text workplace names or geocoding are included."),
 "employer_social_insurance_monthly_contribution_2011_2013":("Employer social-insurance contribution per month (2011/2013)","Employment benefits","FG012 reports the employer's monthly contribution in yuan. It is asked only when the respondent reports knowing the amount; preserve the amount-known route and do not treat missing values as zero."),
 "other_workunit_social_insurance_monthly_contribution_2011_2013":("Other work-unit social-insurance contribution per month (2011/2013)","Employment benefits","FI009 reports the other work unit's monthly contribution in yuan. It is conditional on the other-work-unit route and contribution knowledge; keep it distinct from the current employer's FG012 amount."),
 "planned_retirement_processing_by_current_work_unit_2011_2013":("Whether the current work unit plans to process retirement (2011/2013)","Work and retirement expectations","FD026 is asked of respondents not yet formally retired and records a reported current-work-unit plan, not a completed retirement event or guaranteed entitlement. Preserve the no-retirement route."),
 "retirement_processed_through_current_work_unit_2011_2013":("Whether retirement was processed through the current work unit (2011/2013)","Retirement context","FD028 is asked only of respondents reporting completed retirement and records whether it was processed through the current work unit. Preserve the retired/respondent-preload route; it is distinct from FD026's future plan."),
 "individual_work_injury_insurance_coverage_2013":("Individual report of work-injury insurance coverage (2013)","Employment benefits","FI001_S4 is a respondent-level report of coverage through the current work/social-insurance route. Keep it separate from the employer-provided work-injury-insurance checklist and preserve the eligible social-insurance denominator."),
 "individual_unemployment_insurance_coverage_selfemployment_2013":("Unemployment-insurance coverage through self-employment (2013)","Employment benefits and social protection","FI001_S3 is a checkbox response within the 2013 self-employed social-insurance module, asked only when the respondent has not processed retirement. Preserve the self-employment and retirement-status route. This is individual reported coverage and must remain separate from FG003_S3 (whether an employer provides unemployment insurance) and from job-service-center or other-work-unit coverage routes."),
 "knowledge_of_employer_social_insurance_contribution_amount_2011_2013":("Knowledge of own and employer social-insurance contribution amounts (2011/2013)","Employment benefits and social protection","FG011 is a three-category report of whether the respondent knows their own and the current employer's social-insurance contribution amounts. It is asked only after reporting the employer-route social-insurance coverage. Treat as a route-specific awareness/amount-reporting candidate, not the contribution amount itself; retain its three source categories and do not interpret skipped amount fields as zero."),
 "knowledge_of_other_workunit_social_insurance_contribution_amount_2011_2013":("Knowledge of own and other-work-unit social-insurance contribution amounts (2011/2013)","Employment benefits and social protection","FI008 is a three-category report of whether the respondent knows their own and the other work unit's social-insurance contribution amounts. It is conditional on participation through another work unit (FI003=1); keep separate from employer-route FG011 and from the contribution amount itself. Preserve its three source categories and conditional denominator."),
 "employer_does_not_provide_social_insurance_despite_local_availability_2013":("Employer does not provide social insurance despite local availability (2013)","Employment benefits and social protection","FG004_S2 is one selected reason in a multiple-response item asked when the respondent reports lacking employer-provided social insurance. It indicates the respondent's report that work-based insurance is available locally but the employer does not provide it. Preserve the parent noncoverage route and multi-select semantics; do not infer which named insurance branch or treat unselected/structural missing as No without item-storage validation."),
 "ever_worked_three_months":("Ever worked for at least three months","Work history","2011–2018 lifetime work-history item; not current employment."),
 "never_worked_three_months_confirmation":("Confirmation of never having worked for three months","Work history","2011–2018 confirmation branch with reversed yes/no wording; preserve codes and route, and do not count as a separate analytical construct from lifetime work history."),
 "reason_never_worked_2013_2018":("Reason for never having worked","Work history","2013–2018 conditional on the never-worked history branch; categories vary by wave."),
 "reason_not_working_2011":("Reason for not working (2011)","Work history","2011 wording is broader (‘not work’) than the later never-worked branch; keep as a separate wave-specific measure."),
 "multiple_nonfarm_jobs_2020":("More than one nonfarm job (2020)","Current and recent work","2020-only item; preserve the nonfarm scope and wave-specific job roster context."),
 "farm_work_arrangement_2020":("Farm work arrangement (2020)","Current and recent work","2020 checkbox components identify self-employed farm work and farm employment; option slots use different affirmative codes, and an unselected slot is not a negative response."),
 "nonfarm_work_presence_2020":("Nonfarm work presence (2020)","Current and recent work","2020-only broad nonfarm-work presence item; distinct from the 2018 one-hour/last-month threshold."),
 "job_arrangement_current_2020":("Current job arrangement (2020)","Employment conditions","2020 categories distinguish employed nonfarm, self-employed nonfarm, unpaid family business nonfarm, and farm employment; preserve the nominal categories."),
 "job_arrangement_during_absence_2020":("Job arrangement during temporary absence (2020)","Employment conditions","Asked only after the temporary-absence route; categories describe the job arrangement and must not be treated as current job arrangement."),
 "first_work_start_timing":("Age or calendar year at first work","Work history","The 2011 and 2013 life-history modules ask for age OR calendar year; separate source fields share one construct but have different units. Do not combine without an explicit DOB/year harmonization rule. Not equivalent to the 2020 FB001 agricultural-work location item."),
 "first_job_work_unit_type":("Work-unit type of first job","Work history","Retrospective first-job category (government, institution, NGO, firm, individual firm, farmer, household, other); only available in 2011/2013 life-history module."),
 "first_job_firm_ownership_type":("Ownership type of first-job firm","Work history","Asked only if first job was a firm (FB002=4); structural skip for other first-job types is not a negative response."),
 "career_state_collective_employment":("Ever worked in state-owned or collective enterprise","Work history","Lifetime retrospective item in 2011/2013. FB005 is skipped when first job was a state/collective firm; the full-population indicator may require using FB002/FB003 and preserving the documented branch."),
 "career_state_collective_enterprise_type":("State/collective enterprise ownership type during career","Work history","Conditional detail after career state/collective enterprise exposure; preserve the conditional denominator and codebook categories."),
 "career_long_work_interruption":("Ever had a work interruption longer than one year","Work history","Retrospective interruption threshold is >1 year once; questionnaire excludes current non-employment/retirement and specified periods such as military service/flexible employment. Route and eligible population must be respected."),
 "career_total_interruption_duration":("Total duration of career work interruptions","Work history","Conditional on reporting an interruption; years and months are separate components of the same total-duration construct. Do not interpret missing components as zero."),
 "career_longest_interruption_interval":("Start and end of longest career work interruption","Work history","Conditional on reporting an interruption; year/month components define the interval, but month 0 may mean not remembered. Do not derive precise duration when endpoints are incomplete."),
 "career_interruption_reason":("Main reason for career work interruption","Work history","Conditional on interruption. 2011 questionnaire response codes conflict with official codebook labels (questionnaire lists 1–5; codebook lists 1,2,4,5,6); 2013 codebook matches the questionnaire's 1–5 codes. The 2011 category mapping is blocked pending source reconciliation."),
 "last_business_ownership_type":("Ownership type of last employer/business","Employment conditions","Asked only when the last employer/business is classified as a firm (FL014=1 in 2013; FL014=4 in 2015/2018). Preserve each wave's route and all questionnaire response options. Not a universal employment exposure; skipped government, institution, NGO, individual-business and farmer routes are not negative responses."),
 "government_civil_servant_status":("Civil servant status among government employees","Employment conditions","Asked only among respondents whose employer type is government (FL014=1 in 2013/2015/2018). This is a conditional occupational status, not a general indicator for all employed respondents; structural skips are not No."),
 "pandemic_remote_work":("Remote or home-based work during COVID-19","Pandemic-related work context","2020-only pandemic module. Respect the module selection flag xfgsample; this self-reported context is not a five-wave general work exposure."),
 "pandemic_employer_paid_closure":("Pay received during employer closure in COVID-19 period","Pandemic-related work context","2020-only item; apply xfgsample and preserve the conditional pay-percentage and duration components. Not working-time loss itself."),
 "pandemic_household_farm_work_change":("Household agricultural-work change attributed to COVID-19","Pandemic-related work context","2020-only counterfactual self-report; apply xfgsample. Response includes would-not-work-anyway, less/more work, no effect, and refusal; do not collapse the non-applicable counterfactual to zero."),
 "pandemic_paid_employment_change":("Paid-employment workday change attributed to COVID-19","Pandemic-related work context","2020-only counterfactual self-report; apply xfgsample. Distinct from self-employment and household agriculture; retain weeks-more/fewer components and response category."),
 "pandemic_self_employment_change":("Non-agricultural self-employment change attributed to COVID-19","Pandemic-related work context","2020-only counterfactual self-report; apply xfgsample. Includes freelancing and unpaid family-business assistance but excludes agriculture; retain weeks-more/fewer and the no-work-after-New-Year category."),
 "pandemic_work_hours_change":("Weekly work-hours change attributed to COVID-19","Pandemic-related work context","2020-only counterfactual self-report; apply xfgsample. Questionnaire explicitly says not to double-count full days not worked as reduced hours; retain has-not-worked category separately."),
 "pandemic_unemployment_benefit":("Unemployment-insurance receipt during COVID-19 period","Pandemic-related work context","2020-only report; apply xfgsample. Benefit months and monthly yuan amount are conditional components after a Yes response; low-frequency cells require disclosure review."),
 "pandemic_retirement_plan_shift":("Planned work-stop timing change attributed to COVID-19","Pandemic-related work context","2020-only counterfactual expectation, not observed retirement. Preserve FF004 eligibility and earlier/delayed years; do not assume the FG pandemic-module selection flag xfgsample applies to this FF item. The questionnaire codes health-permitted nonstop work as not affected."),
 "nonfarm_self_employment_business_workforce_size":("Number of workers hired/employed in a non-farm self-employment business","Work organization","Candidate business-size measure, limited to the self-employment business route. 2018 FH009 asks how many people are generally employed at the business/workplace; 2020 FD004 asks how many people are hired and explicitly permits zero. Preserve the different item wording and routes; earlier-wave FD004 is workplace location, not workforce size, and must not be mapped to this concept."),
 "job_search_in_past_month_2020":("Searched for a new job in the past month (2020)","Current and recent work","2020-only self-reported job-search behavior. Questionnaire and codebook give 1=Yes, 2=No. The printed questionnaire does not state a clear skip denominator for FF003; do not equate job search with unemployment or generalize to all respondents without checking release-specific eligibility and observed-data routing."),
 "work_days_in_past_year_2020":("Days actually worked in the past year (2020)","Work intensity","2020 FF001 asks days actually worked in the past year across agricultural work, paid work, running a business, and helping in a family business. Range is 0–366; questionnaire says 0 if no work, -1 if unable to answer, and permits rounding to nearest ten days. This is a broad annual count, not equivalent to any single job-days component; components may overlap and should not be summed."),
 "planned_work_stop_timing_2020":("Planned timing/condition for stopping work (2020)","Work and retirement expectations","2020 FF004 is a self-reported plan about stopping work, with an age, years-from-now, or work-as-long-as-health-permits path; conditional FF004_1/FF004_2 fields have different units. It is not observed retirement or formal retirement age. Verify the released module denominator and preserve the categorical route."),
 "employed_job_months_worked_past_year_2020":("Months worked in the past year at the current employed job (2020)","Work intensity","2020 FC025 is asked in the current employed-work module and refers to that job, not all work. Paid vacation/sick leave are included; questionnaire special case codes 1 month for a full-year vacation without pay. Preserve this caveat and do not equate with months worked across all jobs."),
 "side_job_count_2018":("Number of current side jobs excluding the main job and household agricultural work (2018)","Work organization","2018 FJ001 is routed only when the prior employment roster indicates side job(s); its response range begins at 1. Structural skip is not zero and the item excludes the main job and household agricultural work."),
 "side_job_count_2011":("Number of current jobs excluding the main job (2011)","Work organization","2011 FJ001 is routed after FC019=1 (more than one job) and records 1–20 side jobs. The questionnaire does not explicitly exclude household agricultural work; keep this 2011-only concept separate from the narrower 2018 side-job definition. Structural skip is not zero."),
 "side_job_hours_per_week_2011":("Average weekly hours at side jobs excluding the main job (2011)","Work intensity","2011 FJ002 is routed after FC019=1 and asks average hours per week at side job(s), range 0–168. The questionnaire does not explicitly exclude household agricultural work or specify the 2018 past-year averaging language; keep wave-specific and do not infer zero from structural skip."),
 "side_job_monthly_income_2011":("Average monthly income from side jobs excluding the main job (2011)","Income from work","2011 FJ003 is routed after FC019=1 and asks average monthly income/wage from side jobs in yuan/month; FJ004 supplies unfolding brackets for unwillingness or recall difficulty. The item does not explicitly exclude household agricultural work or specify the 2018 past-year averaging language; keep separate and do not replace missing FJ003 with bracket-derived values without a prespecified protocol."),
 "last_job_nonfarm_hours_per_week_2011_2018":("Usual weekly hours in last non-farm job (2011–2018)","Work intensity","Retrospective last-job measure, not current work hours. FL008 is asked for non-farm work types (FL001=1/2/3); agricultural self-employment skips this branch. Preserve the last-job denominator and do not interpret structural skips as zero."),
 "last_job_monthly_wage_2011_2018":("Monthly wage before stopping last non-farm job (2011–2018)","Income from work","Retrospective amount before stopping the last job. FL009 is routed only for employed work (FL001=1), unlike FL008's broader non-farm job route. 2011/2013/2015 say wages, bonuses and subsidies; 2018 says wages, bonuses and allowance. Questionnaire special values include 0 for no net income and 999997 for a deficit; preserve raw codes and wave-specific wording. Unfolding brackets are separate and must not be silently imputed."),
 "side_job_hours_per_week_2018":("Average weekly hours across side jobs (2018)","Work intensity","2018 FJ002 sums usual hours in side jobs over the past year and excludes the main job and household agricultural work. The side-job route applies; a skipped field is not zero."),
 "side_job_monthly_income_2018":("Average monthly income from side jobs (2018)","Income from work","2018 FJ003 asks total average monthly wage, bonuses, and benefits over the past year across side jobs, excluding the main job and household agricultural work. Yuan/month; side-job route applies and the instrument uses unfolding brackets for nonresponse/uncertainty."),
 "household_agricultural_workforce_size_2018":("Number hired for the respondent's household agricultural work (2018)","Work organization","2018 FC024 asks whether others are employed in household agricultural work and how many. It is distinct from non-farm business size and applies to the household-agriculture route; preserve the prompt's 0–9999 persons range."),
 "last_job_business_workforce_size_2018":("Employees in the respondent's last self-employed non-farm business (2018)","Work organization","2018 FL012 is within the retrospective last-main-job module and is asked only for self-employed business (FL001=2); it refers to a past business, unlike current-business size. Do not combine with current workforce size or other last-job types."),
 "paid_pastime_work_current":("Current paid pastime/recreational work","Work organization","2011–2018 FM054 asks about paid small pastime work; 2020 FF002 asks about pastime work still providing some income. Related but wording changes and reference periods differ; preserve the exact wave-specific labels and eligibility. Do not confuse this with the broader formal job roster."),
 "job_search_in_past_month_2011_2018":("Searched for a new job in the past month (2011-2018)","Current and recent work","The 2011-2015 item says last month and 2018 says past month. It appears in the unemployment/job-search section; it is not an unemployment diagnosis. Preserve the module route and eligible denominator for each wave; missing or skipped values are not No. Keep separate from 2020 FF003 because its questionnaire location/eligibility is not established as equivalent."),
 "non_retirement_compensation_at_job_exit_2011_2015":("Non-retirement compensation received on leaving the last job (2011-2015)","Employment separation benefits","2011-2015 FL021 asks about payments other than the legal retirement allowance on leaving the last job; 2013/2015 examples include condolence payment and workers compensation. The question is retrospective and conditional on last-job history; do not equate with current income, pension benefit, or 2018 severance wording. 2011 questionnaire has the item but the extracted 2011 codebook does not provide a corresponding value distribution."),
 "job_exit_compensation_amount_2011_2015":("Amount of non-retirement compensation on leaving the last job (2011-2015)","Employment separation benefits","Conditional amount component after FL021=Yes, reported in yuan. Preserve the 2011-2015 route and questionnaire special values; do not impute zero to people not asked. It is a retrospective nominal amount and requires inflation/year-aware analysis before cross-wave pooling."),
 "service_years_used_for_compensation_2011_2015":("Years of work associated with compensation at last-job exit (2011-2015)","Employment separation benefits","Conditional FL022_2 response after FL021=Yes; wording asks how many years of work the compensation was based on. It is not necessarily total lifetime work duration or general tenure; preserve as the source-reported compensation basis."),
 "job_exit_severance_package_2018":("Severance package on leaving the last job (2018)","Employment separation benefits","2018 FL021 asks about a severance package other than retirement allowance (examples include lump-sum payment and condolence payment); this wording differs from 2011-2015 FL021, so it remains a separate wave-specific candidate. FL022_W4_1 is the conditional amount in yuan; FL022_W4_3 is years of employment used to compute retirement benefits when forced to leave, not generic tenure."),
 "farm_wage_work_at_least_10days_2011_2018":("Wage work for other farmers/employers for at least 10 days (2011-2018)","Agricultural work and labor conditions","Farm-module status item. 2011-2015 asks about working for other farmers in wage for at least 10 days in the past year; 2018 says other farmers/employers and get paid. It is a specific paid-farm-work component, not equivalent to the broader agricultural-work question FA001. Preserve the wave-specific eligibility route."),
 "farm_wage_months_past_year_2011_2013":("Months in wage agricultural work for other farmers (2011-2013)","Agricultural work and labor conditions","Conditional on the farm-employed route (FC001=Yes). Past-year count, 0-12 months; 2020 reuses FC004 for workplace location and is not included."),
 "farm_wage_days_per_week_2011_2013":("Days per week in wage agricultural work for other farmers (2011-2013)","Agricultural work and labor conditions","Conditional on the farm-employed route. Measures usual days per week during a normal work month in the past year, range stated as 0-7; not annual days and not total work across all jobs."),
 "farm_wage_hours_per_day_2011_2013":("Hours per day in wage agricultural work for other farmers (2011-2013)","Agricultural work and labor conditions","Conditional on the farm-employed route. Usual hours per normal workday in the past year; questionnaire range is 0-16 with a soft-check flag above 16. Retain source values and do not truncate automatically."),
 "farm_wage_monthly_income_2011_2013":("Average monthly wage from wage agricultural work (2011-2013)","Income from work","Conditional on farm-employed work; average yuan per working month in the past year, not annual earnings. Preserve nominal amounts and the working-month denominator; verify release-specific special values before analysis."),
 "household_agricultural_work_at_least_10days_2011_2018":("Household agricultural work for at least 10 days (2011-2018)","Agricultural work and labor conditions","Status of work for the respondent's own household. 2011-2015 questionnaire says at least 10 days; 2018 questionnaire says at least 10 days but its codebook title says at least one month last year. The 2018 item is retained as a candidate with an unresolved questionnaire/codebook route discrepancy and must not be analyzed until clarified."),
 "household_agriculture_months_past_year_2011_2018":("Months in own-household agricultural work (2011-2018)","Agricultural work and labor conditions","Conditional on FC008=Yes. Past-year count, 0-12 months. The 2018 FC008 questionnaire says at least 10 days while the codebook title says at least one month; mark 2018 as DO NOT ANALYZE pending route clarification."),
 "household_agriculture_days_per_week_2011_2018":("Days per week in own-household agricultural work (2011-2018)","Agricultural work and labor conditions","Conditional on FC008=Yes. Usual days per week during a normal work month in the past year, range stated as 0-7. The 2018 FC008 questionnaire says at least 10 days while the codebook title says at least one month; mark 2018 as DO NOT ANALYZE pending route clarification."),
 "household_agriculture_hours_per_day_2011_2018":("Hours per day in own-household agricultural work (2011-2018)","Agricultural work and labor conditions","Conditional on FC008=Yes. Usual hours per normal workday, questionnaire range 0-24 with a soft-check flag above 16. The 2018 FC008 questionnaire says at least 10 days while the codebook title says at least one month; mark 2018 as DO NOT ANALYZE pending route clarification."),
 "nonfarm_job_satisfaction_2015_2018":("Satisfaction with current non-agricultural work (2015-2018)","Employment conditions","Five-category self-reported ordinal satisfaction item in the non-agricultural work route. Preserve the original order and the eligible-worker denominator; do not treat as job quality objectively measured or compare with agricultural-work satisfaction."),
 "planned_age_to_stop_working_general_2011_2015":("Planned age to stop working (2011-2015)","Work and retirement expectations","Self-reported planned age, not observed retirement timing. Map only the general FK003 item; keep separate from current-job FD024 continuation expectation, FC018 wave-specific item wording, 2015/2018 non-agricultural FK000_W3_2, and the 2020 FF004 age/year format family."),
 "planned_age_to_stop_nonfarm_work_2015_2018":("Expected age to stop non-agricultural work (2015-2018)","Work and retirement expectations","Asked in the non-agricultural work route. 2018 codebook values extend to calendar year 2026 although the field is titled age; preserve raw coding and mark 2018 DO NOT ANALYZE until release values/format are clarified. Do not merge with general FK003 or 2020 FF004 year/age components."),
 "self_employed_occupation_code_2011":("Occupation code for self-employed work (2011)","Occupation and industry","2011 self-employment route. Preserve GB and ISCO code systems as separate source fields; do not infer a crosswalk or publish rare codes without disclosure review. Codebook variable labels identify the fields but detailed category meaning requires the corresponding official classification documentation."),
 "self_employed_industry_code_2011":("Industry code for self-employed work (2011)","Occupation and industry","2011 self-employment route; keep distinct from current wage-employment industry and from occupation. Detailed classification and disclosure review are required before analysis or public release of granular codes."),
 "last_job_occupation_code_2011":("Occupation code for the most recent job (2011)","Occupation and industry","Retrospective last-job route; GB and ISCO encodings are preserved separately. Do not combine with current-job occupation or self-employment fields, and review rare categories for disclosure before publication."),
 "last_job_industry_code_2011":("Industry code for the most recent job (2011)","Occupation and industry","Retrospective last-job industry field; distinct from last-job occupation and current-job industry. Detailed classification documentation and disclosure review are needed before analysis or publication of granular codes."),
}
